  sum by (cluster, node) (topolvm_volumegroup_available_bytes{cluster=~"$cluster"})
  and on (cluster, node) (
  (
    group by (cluster, node) (kube_node_spec_unschedulable{cluster=~"$cluster"} == 0)
    unless group by (cluster, node) (kube_node_role{role="control-plane", cluster=~"$cluster"})
  )
  and group by (cluster, node) (
    kube_node_labels{label_node_role_wiremind_io_production="true", cluster=~"$cluster"}
    or kube_node_labels{label_node_role_kubernetes_io_production="true", cluster=~"$cluster"}
  )
)
)

